def apply_transformation(grid):
    """Apply the ARC transformation rule: 1->3, 3->1, 4->1"""
    result = [[grid[r][c] for c in range(len(grid[0]))] for r in range(len(grid))]

    for r in range(len(result)):
        for c in range(len(result[0])):
            val = result[r][c]
            if val == 1:
                result[r][c] = 3
            elif val == 3:
                result[r][c] = 1
            elif val == 4:
                result[r][c] = 1
    return result

